package com.enterprise.proxy

import java.security.PrivilegedAction
import javax.security.auth.Subject
import javax.security.auth.login.LoginContext
import org.ietf.jgss._

object KerberosConfig {
  val DELEGATION_ALLOWED = "delegation.allowed"
  val FORWARDABLE_TGT = "forwardable.tgt"
  val CONSTRAINED_DELEGATION = "constrained.delegation"
  val TRUSTED_BACKENDS = "trusted.backends"
  val PROXY_SERVICE_PRINCIPAL = "proxy.service.principal"
}

case class DelegationPolicy(
  allowDelegation: Boolean,
  constrainedOnly: Boolean,
  trustedBackends: Set[String],
  forwardableTgt: Boolean
)

class DelegationPolicyResolver(env: Map[String, String]) {
  import KerberosConfig._

  private val defaultPolicy = DelegationPolicy(
    allowDelegation = false,
    constrainedOnly = true,
    trustedBackends = Set.empty,
    forwardableTgt = false
  )

  def resolvePolicy(): DelegationPolicy = {
    val delegationAllowed = env.get(DELEGATION_ALLOWED)
      .map(_.trim.toLowerCase)
      .exists(v => v == "true" || v == "1" || v == "yes")

    val constrained = env.get(CONSTRAINED_DELEGATION)
      .map(_.trim.toLowerCase)
      .forall(v => v == "true" || v == "1" || v == "yes")

    val backends = env.get(TRUSTED_BACKENDS)
      .map(_.split(",").map(_.trim).filter(_.nonEmpty).toSet)
      .getOrElse(Set.empty)

    val forwardable = env.get(FORWARDABLE_TGT)
      .map(_.trim.toLowerCase)
      .exists(v => v == "true" || v == "1" || v == "yes")

    DelegationPolicy(
      allowDelegation = delegationAllowed,
      constrainedOnly = constrained,
      trustedBackends = backends,
      forwardableTgt = forwardable
    )
  }
}

class KerberosProxyService(policyResolver: DelegationPolicyResolver, env: Map[String, String]) {
  import KerberosConfig._

  private lazy val policy: DelegationPolicy = policyResolver.resolvePolicy()
  private val servicePrincipal: String = env.getOrElse(PROXY_SERVICE_PRINCIPAL, "HTTP/proxy@REALM")

  def handleIncomingRequest(clientCredential: GSSCredential, targetService: String): Either[String, GSSCredential] = {
    if (!policy.allowDelegation) {
      return Left("Delegation is disabled by policy")
    }

    if (!isTargetAuthorized(targetService)) {
      return Left(s"Target service $targetService is not in trusted backends")
    }

    delegateCredential(clientCredential, targetService)
  }

  private def isTargetAuthorized(targetService: String): Boolean = {
    if (!policy.constrainedOnly) {
      return true
    }
    policy.trustedBackends.contains(targetService) ||
      policy.trustedBackends.exists(pattern => matchesWildcard(pattern, targetService))
  }

  private def matchesWildcard(pattern: String, service: String): Boolean = {
    if (pattern.startsWith("*.")) {
      val suffix = pattern.substring(1)
      service.endsWith(suffix) || service == pattern.substring(2)
    } else {
      pattern == service
    }
  }

  private def delegateCredential(clientCred: GSSCredential, target: String): Either[String, GSSCredential] = {
    try {
      val manager = GSSManager.getInstance()
      val serverName = manager.createName(target, GSSName.NT_HOSTBASED_SERVICE)
      val context = manager.createContext(
        serverName,
        new Oid("1.2.840.113554.1.2.2"),
        clientCred,
        GSSContext.DEFAULT_LIFETIME
      )
      context.requestCredDeleg(policy.forwardableTgt)
      context.requestMutualAuth(true)
      Right(context.getDelegCred)
    } catch {
      case e: GSSException => Left(s"Delegation failed: ${e.getMessage}")
    }
  }
}

object ProxyApplication {
  def createFromEnvironment(): KerberosProxyService = {
    val env = sys.env
    val resolver = new DelegationPolicyResolver(env)
    new KerberosProxyService(resolver, env)
  }

  def createFromConfig(config: Map[String, String]): KerberosProxyService = {
    val resolver = new DelegationPolicyResolver(config)
    new KerberosProxyService(resolver, config)
  }
}
